import sys
from pathlib import Path
import numpy as np

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from src.statistics.bootstrap import bootstrap
from src.statistics.permutation import permutation_test


def main():
    # Demonstration data only.
    # Replace with per-concept human/model similarity scores
    # generated by the actual experiment.
    text_only = np.array([0.51, 0.57, 0.60, 0.55, 0.62, 0.58])
    grounded = np.array([0.69, 0.73, 0.76, 0.71, 0.78, 0.74])

    text_ci = bootstrap(text_only)
    grounded_ci = bootstrap(grounded)

    test = permutation_test(grounded, text_only)

    print("TEXT-ONLY")
    print(text_ci["estimate"], text_ci["lower"], text_ci["upper"])

    print("\nGROUNDED")
    print(
        grounded_ci["estimate"],
        grounded_ci["lower"],
        grounded_ci["upper"],
    )

    print("\nPERMUTATION TEST")
    print("Difference:", test["observed_difference"])
    print("p-value:", test["p_value"])

    print(
        "\nNOTE: The arrays in this demo are illustrative placeholders. "
        "Do not report them as experimental results."
    )


if __name__ == "__main__":
    main()
